def main():
    moved = unmapped = 0
    for f in sorted(os.listdir(ROOT)):
        src = os.path.join(ROOT, f)
        if not os.path.isfile(src) or not f.endswith(".md"):
            continue
        if f not in MAP:
            print("UNMAPPED:", f)
            unmapped += 1
            continue
        folder, newname = MAP[f]
        dst_dir = os.path.join(ROOT, folder)
        os.makedirs(dst_dir, exist_ok=True)
        dst = os.path.join(dst_dir, newname)
        if os.path.exists(dst):
            print("COLLISION:", dst)
            continue
        os.replace(src, dst)
        moved += 1
    print(f"moved={moved} unmapped={unmapped}")
    for d in sorted(os.listdir(ROOT)):
        p = os.path.join(ROOT, d)
        if os.path.isdir(p):
            print(f"  {d}: {len(os.listdir(p))} files")

if __name__ == "__main__":
    main()
